+bool ai7ThumbnailEncodedSizeFits(const DataBuf& src, size_t expectedSize) {
+  constexpr size_t colorTableSize = 256 * 3;
+  if (src.size() < colorTableSize)
+    return true;
+
+  const size_t imageDataSize = src.size() - colorTableSize;
+  return imageDataSize <= expectedSize / 128;
+}
